import java.util.ArrayList;
import java.util.List;

public final class Solution {
    private static final List<List<Integer>> CHILDREN = new ArrayList<>();

    private Solution() {
    }

    public static int[] subtreeSums(int[] parent, int[] value) {
        int n = parent.length;
        while (CHILDREN.size() < n) {
            CHILDREN.add(new ArrayList<>());
        }

        for (int node = 0; node < n; node++) {
            if (parent[node] != -1) {
                CHILDREN.get(parent[node]).add(node);
            }
        }

        int[] sums = new int[n];
        for (int node = 0; node < n; node++) {
            if (parent[node] == -1) {
                compute(node, value, sums);
            }
        }
        return sums;
    }

    private static int compute(int node, int[] value, int[] sums) {
        int sum = value[node];
        for (int child : CHILDREN.get(node)) {
            sum += compute(child, value, sums);
        }
        sums[node] = sum;
        return sum;
    }
}
